define("local_airpay_learningpath/path_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var openPathForm = function(pathid, returnFocus) {
        var titleKey = (pathid === 0) ? "addpath" : "editpath";
        Str.get_string(titleKey, "local_airpay_learningpath").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_learningpath\\form\\edit_path",
                args: {pathid: pathid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmStatus = function(pathid, name, makeActive, returnFocus) {
        var titleKey = makeActive ? "activatepath" : "archivepath";
        var msgKey = makeActive ? "confirmactivate" : "confirmarchive";
        Promise.all([
            Str.get_string(titleKey, "local_airpay_learningpath"),
            Str.get_string(msgKey, "local_airpay_learningpath", name),
            Str.get_string("pathstatuschanged", "local_airpay_learningpath")
        ]).then(function(strings) {
            Notification.confirm(strings[0], strings[1], strings[0], null, function() {
                Ajax.call([{methodname: "local_airpay_learningpath_toggle_status",
                            args: {pathid: pathid, active: makeActive}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[2], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
            });
            if (returnFocus) setTimeout(function() { returnFocus.focus(); }, 100);
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(pathid, name, returnFocus) {
        Promise.all([
            Str.get_string("deletepath", "local_airpay_learningpath"),
            Str.get_string("confirmdelete", "local_airpay_learningpath", name),
            Str.get_string("delete", "core"),
            Str.get_string("pathdeleted", "local_airpay_learningpath")
        ]).then(function(strings) {
            Notification.deleteCancelPromise(strings[0], strings[1], strings[2], returnFocus).then(function() {
                Ajax.call([{methodname: "local_airpay_learningpath_delete_path",
                            args: {pathid: pathid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[3], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var pathid = parseInt(trigger.dataset.pathid || "0", 10);
        var name = trigger.dataset.name || "this path";
        switch (action) {
            case "create-path":   event.preventDefault(); openPathForm(0, trigger); break;
            case "edit-path":     event.preventDefault(); openPathForm(pathid, trigger); break;
            case "archive-path":  event.preventDefault(); confirmStatus(pathid, name, false, trigger); break;
            case "activate-path": event.preventDefault(); confirmStatus(pathid, name, true, trigger); break;
            case "delete-path":   event.preventDefault(); confirmDelete(pathid, name, trigger); break;
        }
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-learningpath"]') || document.body;
            if (root.dataset.airpayLearningpathInit === "1") return;
            root.dataset.airpayLearningpathInit = "1";
            root.addEventListener("click", handleClick);
        }
    };
});
